  "ui.archive.resolved": {"ko": "선택한 Archive DB를 적용했습니다. 두 버전의 백업: {paths}", "en": "Applied the selected Archive database. Backups of both versions: {paths}", "ja": "選択したArchive DBを適用しました。両方のバックアップ: {paths}", "es": "Se aplicó la base de datos de Archive elegida. Copias de ambas versiones: {paths}", "fr": "Base Archive choisie appliquée. Sauvegardes des deux versions : {paths}"},
