  "ui.delete.archiveRecordTitle": {"ko": "Archive에서 지우기", "en": "Remove from Archive", "ja": "Archiveから削除", "es": "Quitar de Archive", "fr": "Retirer d’Archive"},
  "ui.delete.archiveRecord": {"ko": "{count}개를 Archive에서 지웁니다. 실제 ROM/Media 파일은 지워지지 않습니다 - 필요하면 해당 Collection에서 다시 수집할 수 있습니다.", "en": "Remove {count} games from Archive. ROM and media files are kept. You can collect them again from their Collection.", "ja": "Archiveから{count}件削除します。ROMとメディアファイルは保持します。Collectionから再収集できます。", "es": "Quitar {count} juegos de Archive. Se conservan los archivos ROM y multimedia. Puedes recopilarlos de nuevo desde su Collection.", "fr": "Retirer {count} jeux d’Archive. Les fichiers ROM et médias sont conservés. Vous pouvez les recueillir à nouveau depuis leur Collection."},
  "ui.delete.archiveRecordDone": {"ko": "Archive에서 {count}개를 지웠습니다 - 실제 ROM/Media 파일은 그대로입니다.", "en": "Removed {count} games from Archive. ROM and media files are unchanged.", "ja": "Archiveから{count}件削除しました。ROMとメディアファイルはそのままです。", "es": "Se quitaron {count} juegos de Archive. Los archivos ROM y multimedia no cambiaron.", "fr": "{count} jeux retirés d’Archive. Les fichiers ROM et médias sont inchangés."},
  "ui.delete.archiveMetadataTitle": {"ko": "Archive 메타데이터 삭제", "en": "Delete Archive metadata", "ja": "Archiveメタデータを削除", "es": "Eliminar metadatos de Archive", "fr": "Supprimer les métadonnées d’Archive"},
  "ui.delete.archiveMetadata": {"ko": "선택한 {count}개 항목의 Archive 메타데이터를 지웁니다. ROM·미디어·원본 Collection과 출처 Revision은 유지합니다.", "en": "Delete Archive metadata for {count} games. Keep ROMs, media, source Collections and source revisions.", "ja": "{count}件のArchiveメタデータを削除します。ROM、メディア、元のCollectionとRevisionは保持します。", "es": "Eliminar metadatos de Archive de {count} juegos. Se conservan ROMs, multimedia, Collections y revisiones de origen.", "fr": "Supprimer les métadonnées d’Archive de {count} jeux. Conserver les ROM, médias, Collection et révisions sources."},
  "ui.delete.archiveOwnedTitle": {"ko": "Archive Game 전체 삭제", "en": "Delete complete Archive games", "ja": "Archiveゲームをすべて削除", "es": "Eliminar juegos completos de Archive", "fr": "Supprimer les jeux Archive complets"},
  "ui.delete.archiveOwned": {"ko": "Archive가 보관하는 {count}개 게임의 ROM·미디어 파일과 기록을 삭제합니다. 외부 원본에 연결된 게임은 이 동작으로 삭제할 수 없습니다.", "en": "Delete ROMs, media and records of {count} games stored in Archive. Games linked to external sources cannot be deleted this way.", "ja": "Archiveに保管した{count}件のROM、メディア、記録を削除します。外部の元データにリンクしたゲームはこの操作では削除できません。", "es": "Eliminar ROMs, multimedia y registros de {count} juegos guardados en Archive. No se pueden eliminar así juegos vinculados a fuentes externas.", "fr": "Supprimer les ROM, médias et enregistrements de {count} jeux stockés dans Archive. Les jeux liés à des sources externes ne peuvent pas être supprimés ainsi."},
  "ui.delete.archiveRomTitle": {"ko": "Archive 보관 ROM 삭제", "en": "Delete ROMs stored in Archive", "ja": "Archiveに保管したROMを削除", "es": "Eliminar ROMs guardadas en Archive", "fr": "Supprimer les ROM stockées dans Archive"},
  "ui.delete.archiveRom": {"ko": "선택한 {count}개 항목에서 Archive ROM 디렉토리 안의 파일만 삭제합니다. 외부 Collection의 원본 연결은 그대로 유지합니다.", "en": "For {count} selected games, delete only files inside the Archive ROM directory. Keep links to source files in external Collections.", "ja": "選択した{count}件のArchive ROMフォルダー内のファイルだけを削除します。外部Collectionの元ファイルへのリンクは保持します。", "es": "Eliminar solo archivos de la carpeta ROM de Archive para {count} juegos. Se conservan enlaces a los originales de Collections externas.", "fr": "Pour {count} jeux, supprimer uniquement les fichiers du dossier ROM d’Archive. Conserver les liens vers les originaux des Collection externes."},
  "ui.delete.archiveMetadataDone": {"ko": "Archive 메타데이터 {count}개를 지웠습니다.", "en": "Cleared Archive metadata for {count} games.", "ja": "{count}件のArchiveメタデータを削除しました。", "es": "Se borraron los metadatos de Archive de {count} juegos.", "fr": "Métadonnées d’Archive effacées pour {count} jeux."},
