  "ui.backend.f5b152f575": {"ko": "원본 Collection에서 다른 작업이 진행 중입니다.", "en": "Another operation is running in source Collection.", "ja": "元Collectionで他の作業中。", "es": "Otra operación en Collection origen.", "fr": "Autre opération dans la Collection source."},
